// Generated by vibelang from worker/branch/ConversationPeople.ts; the migrate flow writes it again with each batch.
import { Effect } from "effect";
import { SqlClient } from "effect/sql";
// The statements behind a person's own list of conversations (decision 0013 decision 2,
// docs/features/conversations.md#postgres): one `conversation_people` row per person and conversation, with its branch
// as they last opened it. Archive is personal: it changes only the person's own row. The latest act wins whatever order
// acts arrive in, by `changed_at`; opening the branch is an act too, which brings the conversation back.
/**
 * The person opened conversation `conversationId`'s branch, `branch` of `owner/repo`, at `at` (milliseconds since the
 * epoch; without one, now): it joins their list, its names are refreshed, and, unless they archived it later, it is no
 * longer archived. The same open tried again after a lost answer carries the same `at`, so it never undoes an archive
 * made since, nor moves the conversation up the list.
 */
export const opened = (conversationId, personId, owner, repo, branch, at) => Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    const when = at === undefined ? sql `now()` : sql `${new Date(at)}::timestamptz`;
    yield* sql `
      INSERT INTO conversation_people (conversation_id, person_id, owner, repo, branch, opened_at, changed_at)
      VALUES (${conversationId}, ${personId}, ${owner}, ${repo}, ${branch}, ${when}, ${when})
      ON CONFLICT (conversation_id, person_id) DO UPDATE SET
        owner = EXCLUDED.owner, repo = EXCLUDED.repo, branch = EXCLUDED.branch,
        opened_at = greatest(conversation_people.opened_at, EXCLUDED.opened_at),
        archived_at = CASE WHEN conversation_people.changed_at < EXCLUDED.changed_at
          THEN NULL ELSE conversation_people.archived_at END,
        changed_at = greatest(conversation_people.changed_at, EXCLUDED.changed_at)`;
});
/**
 * The person asked in conversation `conversationId`: it joins their list, named for its branch as the app tracks it.
 * Asking never brings back a conversation they archived (decision 0013 §6).
 */
export const asked = (conversationId, personId) => Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql `
      INSERT INTO conversation_people (conversation_id, person_id, owner, repo, branch)
      SELECT c.id, ${personId}, split_part(b.repo_id, '/', 2), split_part(b.repo_id, '/', 3), b.name
      FROM conversations c JOIN branches b ON b.id = c.branch_id WHERE c.id = ${conversationId}
      ON CONFLICT (conversation_id, person_id) DO NOTHING`;
});
/**
 * The person archived conversation `conversationId` at `at` (milliseconds since the epoch), or, with `archived` false,
 * brought it back. An act older than the row's latest changes nothing, so sending one twice changes nothing either.
 * Answers the transaction that wrote it, or `null` when it changed nothing.
 */
export const archive = (conversationId, personId, archived, at) => Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    const when = new Date(at);
    const [row] = yield* sql `
      INSERT INTO conversation_people (conversation_id, person_id, owner, repo, branch, archived_at, changed_at)
      SELECT c.id, ${personId}, split_part(b.repo_id, '/', 2), split_part(b.repo_id, '/', 3), b.name,
        ${archived ? when : null}, ${when}
      FROM conversations c JOIN branches b ON b.id = c.branch_id WHERE c.id = ${conversationId}
      ON CONFLICT (conversation_id, person_id) DO UPDATE SET
        archived_at = EXCLUDED.archived_at, changed_at = EXCLUDED.changed_at
      WHERE conversation_people.changed_at < EXCLUDED.changed_at
      RETURNING pg_current_xact_id()::xid::text AS txid`;
    return row === undefined ? null : Number(row.txid);
});
